 13	// 渲染器焦点请求负载：只带不透明上下文编号、字段名与动作类型，平台不解释几何。
 14	// action 缺省视为 "focus"（向后兼容无 action 的旧负载）。
 15	// action="restore"：框架侧把代理拉回 owner 已接受的值与落点（拒绝编辑回滚、
 16	// 外部换版后重设选区），载荷带该值与其 UTF-16 选区；同一上下文内复位，不重挂。
 17	interface ImeFocusPayload {
 18	  action?: string;
 19	  context: number;
 20	  field: string;
 21	  oldContext?: number;
 22	  baseVersion?: number;
 23	  selStart?: number;
 24	  selEnd?: number;
 25	  text?: string;
 26	  request?: number;
 27	}
