 39	// 一次平台安装任务（H1-R.a/b）。请求账本与观测账本彻底分开：
 40	// target* 是签发前冻结的规范目标，observed* 是组件自己报告的实际落点，
 41	// 只有后者精确等于前者才允许回报"安装成功"。
 42	class ProxyRestoreTask {
 43	  mount: CjguiTextProxyMount;
 44	  request: number;
 45	  targetText: string;
 46	  targetStart: number;
 47	  targetEnd: number;
 48	  needsText: boolean;
 49	  textObserved: boolean;
 50	  selectionRetried: boolean;
 51	  terminal: boolean;
 52	  constructor(mount: CjguiTextProxyMount, request: number, targetText: string,
 53	    targetStart: number, targetEnd: number, needsText: boolean) {
 54	    this.mount = mount;
 55	    this.request = request;
 56	    this.targetText = targetText;
 57	    this.targetStart = targetStart;
 58	    this.targetEnd = targetEnd;
 59	    this.needsText = needsText;
 60	    this.textObserved = !needsText;
 61	    this.selectionRetried = false;
 62	    this.terminal = false;
 63	  }
 64	}
