445	  // 由注册表按 ProxyKey 校验；'stale' 裁决只记日志，绝不影响当前挂载。
446	  @Builder
447	  proxyTextInput(m: CjguiTextProxyMount | null) {
448	    if (m !== null) {
449	      TextArea({ text: this.imeText, controller: this.imeTextController })
450	        .id(m.controlId)
451	        .enablePreviewText(true)
452	        .enterKeyType(EnterKeyType.NEW_LINE)
453	        .opacity(0.01)
454	        .position({ x: this.imeX, y: this.imeY })
455	        .width(this.imeW)
456	        .height(this.imeH)
457	        // 代理只经程序化焦点请求取焦（native 点正文 → 命中 → focus request 已覆盖
458	        // "点正文取焦"）。focusOnTouch/命中必须关：代理几何覆盖正文区，开着时编辑中
459	        // 的每次真实点击都被这个单行 TextInput 吞掉——它按单行排版移动自己的光标
460	        // 再回声给 native，把多行命中结果覆盖掉（实测 tap→caret 恒落在旧偏移）。
461	        .focusable(true)
462	        .focusOnTouch(false)
463	        .hitTestBehavior(HitTestMode.None)
464	        .onFocus(() => {
465	          if (!this.proxyRegistry.isCurrent(m)) {
466	            hilog.info(DOMAIN, TAG, 'ime stale focus ignored mount=%{public}s', m.key.describe());
467	            return;
468	          }
469	          // 用户可见的聚焦信号（底部状态栏），同时日志留痕。
470	          this.proxyFocused = true;
471	          this.status = `editing ${m.fieldId}: 已聚焦，回车换行`;
472	          hilog.info(DOMAIN, TAG, 'ime proxy FOCUSED field=%{public}s mount=%{public}s',
473	            m.fieldId, m.key.describe());
474	          if (this.proxySelMount === m) {
475	            // 聚焦达成的这一帧平台把光标推到末尾：按上下文立刻重装一次。
476	            this.installProxySelection(m, this.proxySelStart, this.proxySelEnd, 0,
477	              this.proxySelSeq, 'focus');
478	          }
479	        })
480	        .onChange((value: string, previewText?: PreviewText) => {
481	          // 程序回声判定：必须是**本次挂载**的回声且携带**本次请求的目标文本**。
482	          // 旧挂载的回声先被拒；文本不同的（人真的打了字）照常走真实输入路径，
483	          // 绝不能被一个全局门禁吞掉。
484	          const task: ProxyRestoreTask | null = this.proxyRestoreTask;
485	          if (task !== null && !task.terminal && task.mount === m && task.needsText &&
486	            value === task.targetText) {
487	            // 正文证据成立：只推进阶段，不发成功 ACK（选区还没装）。同一截止继续
488	            // 覆盖后面的选择阶段，不重新计时。
489	            task.textObserved = true;
490	            m.draft = value;
491	            this.proxyRestoreTask = task;
492	            hilog.info(DOMAIN, TAG,
493	              'ime proxy onChange is program echo req=%{public}d len=%{public}d', task.request, value.length);
494	            // 赋值把光标重置到末尾是平台的既有行为（华为 FAQ）：等这一帧的重置落定
495	            // 再装选区，否则 setTextSelection 会被随后的重置覆盖。
496	            setTimeout(() => {
497	              this.beginSelectionPhase(task);
498	            }, 30);
499	            return;
500	          }
501	          if (task !== null && !task.terminal && task.mount === m && value !== task.targetText) {
502	            // 真人输入先于程序回声到达：安装已被人的输入取代，如实回报失败，
503	            // 让窗口按有界重试重新签发，而不是把这次变化当回声丢掉。
504	            task.terminal = true;
505	            this.proxyRestoreTask = null;
506	            hilog.info(DOMAIN, TAG,
507	              'ime restore superseded by human input req=%{public}d len=%{public}d',
508	              task.request, value.length);
509	            this.ackProxyRestore(m.key.contextId, task.request, 0, 0, false, 'superseded_by_input');
510	          }
511	          const composing: boolean = previewText !== undefined && previewText !== null
512	            && previewText.value !== undefined && previewText.value.length > 0;
513	          if (composing) {
514	            hilog.info(DOMAIN, TAG, 'ime proxy composition len=%{public}d offset=%{public}d',
515	              previewText!.value.length, previewText!.offset ?? 0);
516	          }
517	          if (this.proxySelMount === m && value !== m.draft) {
518	            // 真人改文优先于落点安装：不再把光标拉回 native 推来的旧位置。
519	            this.proxySelMount = null;
520	          }
521	          const verdict: string = this.proxyRegistry.onChange(m, value, previewText);
522	          hilog.info(DOMAIN, TAG, 'ime proxy onChange len=%{public}d verdict=%{public}s mount=%{public}s',
523	            value.length, verdict, m.key.describe());
524	          if (verdict === 'ok') {
525	            this.imeText = m.draft;
526	          } else if (verdict === 'rejected') {
527	            this.imeLastClosedCtx = m.key.contextId;
528	            if (this.imeCtx === m.key.contextId) {
529	              this.imeMount = null;
530	              this.imeCtx = 0;
531	              this.mountedBaseVersion = 0;
532	              this.mountedNodeId = 0;
533	            }
534	            this.status = `editing closed: preview rejected`;
535	          }
536	          // 'stale'：迟到/退役实例，仅日志，当前挂载与显示不受影响。
537	        })
538	        .onSubmit(() => {
539	          const verdict: string = this.proxyRegistry.submitAndFinish(m, 'submit');
540	          hilog.info(DOMAIN, TAG, 'ime proxy submit verdict=%{public}s mount=%{public}s',
541	            verdict, m.key.describe());
542	          this.recordProxyFinish(m, verdict, 'submit');
543	        })
544	        .onTextSelectionChange((selectStart: number, selectEnd: number) => {
545	          // 先验挂载身份再记账：旧组件退役后的迟到选择事件不得写当前观测账本，
546	          // 否则新挂载的待办会被上一代事件满足（H1-R 复核 e2 反例）。
547	          if (!this.proxyRegistry.isCurrent(m)) {
548	            hilog.info(DOMAIN, TAG, 'ime stale selection ignored [%{public}d,%{public}d) mount=%{public}s',
549	              selectStart, selectEnd, m.key.describe());
550	            return;
551	          }
552	          const task: ProxyRestoreTask | null = this.proxyRestoreTask;
553	          if (task !== null && !task.terminal && task.mount === m && task.textObserved) {
554	            // 恢复进行中的选择事件属于安装观测流：用它触发按票据的复核，
555	            // 不上报成人的导航，也不改写会话/书签。
556	            hilog.info(DOMAIN, TAG, 'ime restore selection observed [%{public}d,%{public}d) req=%{public}d',
557	              selectStart, selectEnd, task.request);
558	            this.observeSelection(task);
559	            return;
560	          }
561	          this.imeSelStart = selectStart;
562	          this.imeSelEnd = selectEnd;
563	          if (this.proxySelMount === m && selectStart === this.proxySelStart &&
564	            selectEnd === this.proxySelEnd) {
565	            // 代理已观测到目标落点：安装收口，不再重投（重投只会和人后续的
566	            // 导航抢光标）。这次回声把 native 的值带回渲染器。
567	            this.proxySelMount = null;
568	          }
569	          const rc: string = entryNapi.imeSetSelection(selectStart, selectEnd, m.key.contextId) as string;
570	          hilog.info(DOMAIN, TAG, 'ime select [%{public}d,%{public}d) rc=%{public}s mount=%{public}s',
571	            selectStart, selectEnd, rc, m.key.describe());
572	        })
573	        .onBlur(() => {
574	          if (!this.proxyRegistry.isCurrent(m)) {
575	            hilog.info(DOMAIN, TAG, 'ime stale blur ignored mount=%{public}s', m.key.describe());
576	            return;
577	          }
578	          this.proxyFocused = false;
579	          const verdict: string = this.proxyRegistry.submitAndFinish(m, 'blur');
580	          hilog.info(DOMAIN, TAG, 'ime proxy blur verdict=%{public}s mount=%{public}s',
581	            verdict, m.key.describe());
582	          this.recordProxyFinish(m, verdict, 'blur');
583	        })
584	        .onDisAppear(() => {
585	          this.onProxyDisappeared(m);
586	        })
587	    }
588	  }
