590	  // 平台只确认回调被接受；领域事务须由公开 GET_CONTEXT 精确读回。
591	  private recordProxyFinish(m: CjguiTextProxyMount, verdict: string, reason: string): void {
592	    if (verdict === 'stale') {
593	      return;
594	    }
595	    this.imeLastCommitRc = verdict;
596	    this.imeLastClosedCtx = m.key.contextId;
597	    if (this.sameDisplayedMount(m)) {
598	      this.imeMount = null;
599	      this.imeCtx = 0;
600	      this.mountedBaseVersion = 0;
601	      this.mountedNodeId = 0;
602	      this.proxyFocused = false;
603	    }
604	    this.status = verdict === 'ok'
605	      ? `input sent (${reason}); owner value: GET_CONTEXT`
606	      : `input rejected (${reason}); inspect owner via GET_CONTEXT`;
607	  }
608	
609	  private sameDisplayedMount(m: CjguiTextProxyMount): boolean {
610	    const current: CjguiTextProxyMount | null = this.imeMount;
611	    return current !== null && current.key.mountGeneration === m.key.mountGeneration &&
612	      current.key.contextId === m.key.contextId &&
751	  // 框架侧回滚（action="restore"）。同一上下文内的状态复位：把显示正文与落点拉回
752	  // owner 已接受的事实。身份按当前挂载校验后原地更新，不换上下文编号、不重挂
753	  // TextInput，因此焦点与系统输入会话都保持，人不需要再点一次就能继续打字。
754	  //
755	  // 分阶段安装（H1-R.a，按 Astra 裁决的实施顺序）：
756	  //   1. 冻结任务与真实挂载；2. 需要改文时才发起一次文本写入；3. 只有同挂载的目标值
757	  //   回声才算正文证据（回声只推进阶段，不发成功 ACK）；4. 正文写入会让平台把光标
758	  //   重置到末尾（华为 FAQ），因此选区必须在文本更新之后装；5. `setTextSelection` 之后
759	  //   用组件自己的 `getSelection()` 观测实际落点；6. 观测精确等于规范目标才回报成功，
760	  //   否则在同一截止内重试一次选区阶段，再不符就具名失败。
761	  // 请求账本（这张任务）与观测账本（imeSel*）互不代替：setter 抛错时观测账本保持不变，
762	  // 相同区间的重试仍会真实执行，不会靠缓存相等发成功。
763	  private onProxyRestore(payload: ImeFocusPayload): void {
764	    const ctx: number = payload.context;
765	    const request: number = payload.request ?? 0;
766	    if (this.imeCtx === 0 || ctx !== this.imeCtx) {
767	      // 迟到回滚：旧上下文/退役载，绝不允许它改写当前显示，也不得回报成功。
768	      hilog.info(DOMAIN, TAG, 'ime restore ignored ctx=%{public}d active=%{public}d req=%{public}d',
769	        ctx, this.imeCtx, request);
770	      this.ackProxyRestore(ctx, request, 0, 0, false, 'stale_context');
771	      return;
772	    }
773	    const mount: CjguiTextProxyMount | null = this.imeMount;
774	    if (mount === null || mount.key.contextId !== ctx ||
775	      (payload.field !== undefined && payload.field.length > 0 && payload.field !== mount.fieldId)) {
776	      hilog.info(DOMAIN, TAG, 'ime restore ignored: live identity mismatch ctx=%{public}d req=%{public}d',
777	        ctx, request);
778	      this.ackProxyRestore(ctx, request, 0, 0, false, 'identity_mismatch');
779	      return;
780	    }
781	    const start: number = payload.selStart ?? -1;
782	    const end: number = payload.selEnd ?? -1;
783	    const text: string = typeof payload.text === 'string' ? payload.text : this.imeText;
784	    const live: ProxyRestoreTask | null = this.proxyRestoreTask;
785	    if (live !== null && live.request === request && !live.terminal &&
786	      live.targetText === text && live.targetStart === start && live.targetEnd === end) {
787	      // 同一请求的重复下发：继续等这张任务的观测，不重复写正文。
788	      return;
789	    }
790	    if (live !== null && !live.terminal) {
791	      // 目标已改变：先给旧任务确定终态，禁止活跃槽被无声覆写。
792	      this.ackProxyRestore(ctx, live.request, this.imeSelStart, this.imeSelEnd, false, 'superseded_in_shell');
793	    }
794	    if (start < 0 || end < start) {
795	      this.ackProxyRestore(ctx, request, 0, 0, false, 'invalid_target');
796	      return;
797	    }
798	    const needsText: boolean = text !== this.imeText;
799	    const task = new ProxyRestoreTask(mount, request, text, start, end, needsText);
800	    this.proxyRestoreTask = task;
801	    this.proxySelMount = null; // 恢复事务接管落点安装
802	    if (needsText) {
803	      // 只发起一次文本写入；成功与否由同挂载携带目标值的回声决定。
804	      this.imeText = text;
805	      this.status = `proxy restoring ctx=${ctx}`;
806	      this.armRestoreDeadline(task, 1500);
807	      return;
808	    }
809	    this.beginSelectionPhase(task);
810	  }
811	
812	  // 阶段截止：到期一律给终态。旧版只清 pendingEcho 不回报失败，native 的 awaitingAck
813	  // 与窗口的待办就这样永远挂着，输入门永久关闭（H1-R.b 实测形状）。
814	  private armRestoreDeadline(task: ProxyRestoreTask, ms: number): void {
815	    setTimeout(() => {
816	      const live: ProxyRestoreTask | null = this.proxyRestoreTask;
817	      if (live !== task || task.terminal) {
818	        return;
819	      }
820	      task.terminal = true;
821	      this.proxyRestoreTask = null;
822	      const reason: string = task.textObserved ? 'selection_observation_timeout' : 'text_observation_timeout';
823	      hilog.warn(DOMAIN, TAG, 'ime restore timeout req=%{public}d ctx=%{public}d reason=%{public}s',
824	        task.request, task.mount.key.contextId, reason);
825	      this.ackProxyRestore(task.mount.key.contextId, task.request,
826	        this.imeSelStart, this.imeSelEnd, false, reason);
827	    }, ms);
828	  }
829	
830	  private beginSelectionPhase(task: ProxyRestoreTask): void {
831	    if (task.terminal || !this.proxyRegistry.isCurrent(task.mount)) {
832	      return;
833	    }
834	    // 调用前只记"已发出选择命令"：抛错就不更新观测、如实失败，不谎报成功。
835	    try {
836	      if (task.targetStart === task.targetEnd) {
837	        this.imeTextController.caretPosition(task.targetStart);
838	      } else {
839	        this.imeTextController.setTextSelection(task.targetStart, task.targetEnd);
840	      }
841	    } catch (err) {
842	      task.terminal = true;
843	      this.proxyRestoreTask = null;
844	      hilog.warn(DOMAIN, TAG, 'ime restore selection threw: %{public}s', String(err));
845	      this.ackProxyRestore(task.mount.key.contextId, task.request, 0, 0, false, 'selection_threw');
846	      return;
847	    }
848	    this.observeSelection(task);
849	  }
850	
851	  // 安装由观测收口：以组件自己报告的区间为准，而不是请求值。
852	  private observeSelection(task: ProxyRestoreTask): void {
853	    if (task.terminal || !this.proxyRegistry.isCurrent(task.mount)) {
854	      return;
855	    }
856	    let observedStart: number = -1;
857	    let observedEnd: number = -1;
858	    try {
859	      const range: TextRange = this.imeTextController.getSelection();
860	      if (range === undefined || range === null) {
861	        // 控制器未绑定组件/组件已释放：没有观测可用，不得当作"落点已确认"。
862	        hilog.warn(DOMAIN, TAG, 'ime restore selection query has no bound component');
863	      } else {
864	        // TextRange.start/end 在本机声明里是可选 number：缺位就是"没有观测"，
865	        // 不得当成 0（0 是一个合法落点）。
866	        observedStart = range.start !== undefined ? range.start : -1;
867	        observedEnd = range.end !== undefined ? range.end : -1;
868	      }
869	    } catch (err) {
870	      hilog.warn(DOMAIN, TAG, 'ime restore selection query threw: %{public}s', String(err));
871	    }
872	    if (observedStart >= 0 && observedEnd >= observedStart) {
873	      // 观测账本只由组件报告的值推进。
874	      this.imeSelStart = observedStart;
875	      this.imeSelEnd = observedEnd;
876	    }
877	    if (observedStart === task.targetStart && observedEnd === task.targetEnd) {
878	      task.terminal = true;
879	      this.proxyRestoreTask = null;
880	      task.mount.draft = task.targetText;
881	      hilog.info(DOMAIN, TAG, 'ime restore observed installed req=%{public}d sel=%{public}d,%{public}d',
882	        task.request, observedStart, observedEnd);
883	      this.ackProxyRestore(task.mount.key.contextId, task.request, observedStart, observedEnd, true,
884	        'observed_installed');
885	      this.status = `proxy restored ctx=${task.mount.key.contextId} units=${task.targetText.length}`;
886	      return;
